WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_rt_time'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '往返时间比较', 'kp-trv-rt-time', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "往返时间比较"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "往返过程中涉及风向、水流导致速度不同，通过时间差反求路程或静水速度。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“去时顺风，回时逆风，去比回少用 2 小时”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "通过 S=VT 的正反比关系，由速度比倒推时间比，进而用真实时间差解出真实时间。"}]}, {"type": "katexBlock", "attrs": {"content": "\\Delta T = T_{回} - T_{去} = \\frac{S}{V_{回}} - \\frac{S}{V_{去}}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出去程速度 V去 和 回程速度 V回] --> B[求出速度比 V去 : V回]\nB --> C[反转得到时间比 T去 : T回]\nC --> D[算出时间比的份数差]\nD --> E[用真实的往返时间差 ÷ 份数差 = 1份时间]\nE --> F[求出去程或回程的具体真实时间]\nF --> G[用真实时间 × 对应的速度 = 总路程 S]"}}]}$$ AS jsonb), NULL, '往返时间比较的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "往返时间比较"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_rt_time", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
